/**
 * Generates sql/seed.sql from js/products-data.js (the storefront's price list),
 * so the products in Supabase always match what the site shows and charges.
 *
 *   npm run db:seed-sql   then paste sql/seed.sql into the Supabase SQL Editor.
 */
const fs = require('fs');
const path = require('path');
const { HIPA_PRODUCTS } = require('../js/products-data.js');

const q = value => (value == null ? 'null' : `'${String(value).replace(/'/g, "''")}'`);

const lines = [
  '-- GENERATED by scripts/generate-seed-sql.js from js/products-data.js. Do not edit by hand.',
  '-- Safe to re-run: updates existing products and prices.',
  'begin;',
  ''
];

for (const p of HIPA_PRODUCTS) {
  const first = p.variants[0];
  lines.push(
    `insert into public.products (name, slug, tamil_name, description, price, pack_size, image, category, stock_status, is_active)`,
    `values (${q(p.name)}, ${q(p.slug)}, ${q(p.tamilName)}, ${q(p.description)}, ${first.price}, ${q(first.size)}, ${q(p.image)}, ${q(p.category)}, 'in_stock', true)`,
    `on conflict (slug) do update set name = excluded.name, tamil_name = excluded.tamil_name, description = excluded.description,`,
    `  price = excluded.price, pack_size = excluded.pack_size, image = excluded.image, category = excluded.category;`,
    ''
  );
  p.variants.forEach((v, i) => {
    lines.push(
      `insert into public.product_variants (product_id, size, price, sort_order)`,
      `select id, ${q(v.size)}, ${v.price}, ${i} from public.products where slug = ${q(p.slug)}`,
      `on conflict (product_id, size) do update set price = excluded.price, sort_order = excluded.sort_order;`
    );
  });
  const sizes = p.variants.map(v => q(v.size)).join(', ');
  lines.push(
    `delete from public.product_variants where product_id = (select id from public.products where slug = ${q(p.slug)}) and size not in (${sizes});`,
    ''
  );
}

const slugs = HIPA_PRODUCTS.map(p => q(p.slug)).join(', ');
lines.push(`update public.products set is_active = (slug in (${slugs}));`, '', 'commit;', '');

const out = path.join(__dirname, '..', 'sql', 'seed.sql');
fs.writeFileSync(out, lines.join('\n'), 'utf8');
console.log(`Wrote ${out} (${HIPA_PRODUCTS.length} products, ${HIPA_PRODUCTS.reduce((n, p) => n + p.variants.length, 0)} pack sizes)`);
